/* ==========================================================================
   Mi RCR — pies.js
   Pie institucional por área (franja de aliados) como PNG embebido en data URI.
   Se coloca a ancho útil A4 y centrado, respetando su proporción. "ar" = ancho/alto.
   ========================================================================== */

window.PIES = {
  /* Pie ReCircula — 896x73 */
  recircula: { ar: 12.274, src: "data:image/png;base64," },
  /* Pie Juntos Por La Vida — 907x66 */
  juntos_vida: { ar: 13.7424, src: "data:image/png;base64," },
  /* Pie Vidrio Mejor Planeta — 894x86 */
  vidrio: { ar: 10.3953, src: "data:image/png;base64," },
  /* Pie Redes Con Rostro — 848x220 */
  redes: { ar: 3.8545, src: "data:image/png;base64," }
};

window.pieImg = function (areaKey, ancho) {
  var Q = window.PIES[areaKey];
  return Q ? '<img src="'+Q.src+'" alt="" style="width:'+ancho+'px;height:auto;display:block">' : '';
};
